expr:
return `att:${blake3Hex(
    canonical({
      attemptId: event.attemptId,
      phase: event.phase,
      subject: event.subject,
      observation: event.observation,
      action: event.action,
      outcome: event.outcome,
      candidateId: event.candidateId,
      evaluationId: event.evaluationId,
    }),
  )}`;

return `rcpt:${blake3Hex(
    canonical({
      policyHash: receipt.policyHash,
      profileHash: receipt.profileHash,
      executable: receipt.executable,
      args: receipt.args,
      head: receipt.head,
      worktreeDigest: receipt.worktreeDigest,
      exitCode: receipt.exitCode,
      outputDigest: receipt.outputDigest,
      assertions: receipt.assertions,
      runner: receipt.runner,
    }),
  )}`;

return `dec:${blake3Hex(
    canonical({
      kind: decision.kind,
      subject: decision.subject,
      successor: decision.successor,
      actor: decision.actor,
      reason: decision.reason,
    }),
  )}`;

return `fb:${blake3Hex(
    canonical({
      signal: feedback.signal,
      subject: feedback.subject,
      actor: feedback.actor,
      context: feedback.context,
    }),
  )}`;

return canonical({
    kind: input.kind,
    subject: input.subject,
    claim: normalizeClaim(input.claim),
    scope: scopeHash(input.scope),
    appliesTo: [...input.appliesTo].sort(),
    evidence: evidenceHash(input.evidence),
    authorship: { actor: input.authorship.actor, kind: input.authorship.kind },
  });

signature:
attemptEventId(event: {
  attemptId: string;
  phase: AttemptEvent['phase'];
  subject?: string;
  observation?: AttemptEvent['observation'];
  action?: AttemptEvent['action'];
  outcome?: AttemptEvent['outcome'];
  candidateId?: string;
  evaluationId?: string;
}): string

attemptGroupId(seed: {
  subject?: string;
  actor: string;
  startedAt: string;
  origin: 'observe' | 'attempt';
}): string

claimBody(input: {
  kind: string;
  subject: string;
  claim: string;
  scope: MemoryScope;
  appliesTo: string[];
  evidence: MemoryEvidence[];
  authorship: { actor: string; kind: string };
}): string

decisionId(decision: {
  kind: MemoryDecision['kind'];
  subject: string;
  successor?: string;
  actor: string;
  reason?: string;
}): string

feedbackId(feedback: {
  signal: MemoryFeedback['signal'];
  subject: string;
  actor: string;
  context?: string;
}): string

memoryCandidateId(candidate: {
  kind: MemoryCandidate['kind'];
  subject: string;
  claim: string;
  scope: MemoryScope;
  appliesTo: string[];
  evidence: MemoryEvidence[];
  authorship: MemoryCandidate['authorship'];
}): string

memoryRecordId(record: {
  kind: MemoryRecord['kind'];
  subject: string;
  claim: string;
  scope: MemoryScope;
  appliesTo: string[];
  evidence: MemoryEvidence[];
  authorship: MemoryRecord['authorship'];
}): string

receiptId(receipt: {
  policyHash: string;
  profileHash: string;
  executable: string;
  args: string[];
  head: string;
  worktreeDigest: string;
  exitCode: number;
  outputDigest: string;
  assertions: GateReceipt['assertions'];
  runner: GateReceipt['runner'];
}): string
